def decimal_to_binary(decimal):
    """Convert a decimal number to binary format, with 'db' prefix and suffix."""
    if decimal == 0:
        return "db0db"
    binary = ""
    while decimal > 0:
        binary = str(decimal % 2) + binary
        decimal = decimal // 2
    return "db" + binary + "db"

def decimal_to_binary(decimal):
    binary = bin(decimal)[2:]
    return f"db{binary}db"

